   132→public(package) fun support_asset<CoinType>(registry: &mut EModeGroupRegistry, group: u8, params: NewEMode, ctx: &mut TxContext) {
   133→    assert!(registry.groups.contains(group), error::emode_group_not_exists());
   134→
   135→    let group = registry.groups.borrow_mut(group);
   136→    assert!(!group.assets.supports<EMode, CoinType>(), error::emode_group_already_supports_asset());
   137→
   138→    let mut emode = EMode { id: object::new(ctx) };
   139→
   140→    let NewEMode {
   141→        collateral_factor,
   142→        liquidation_factor,
   143→        liquidation_incentive,
   144→
   145→        max_borrow_amount,
   146→        borrow_weight,
   147→
   148→        flash_loan_fee_rate,
   149→
   150→        deposit_limiter,
   151→        borrow_limiter,
   152→    } = params;
   153→
   154→    let collateral = EModeCollateral {
   155→        collateral_factor: collateral_factor,
   156→        liquidation_factor: liquidation_factor,
   157→        liquidation_incentive: liquidation_incentive,
   158→    };
   159→
   160→    dynamic_field::add(&mut emode.id, DFKey<EModeCollateral> {}, collateral);
   161→
   162→    let borrow = EModeBorrow {
   163→        max_borrow_amount: max_borrow_amount,
   164→        borrow_weight: borrow_weight,
   165→    };
   166→    dynamic_field::add(&mut emode.id, DFKey<EModeBorrow> {}, borrow);
   167→
   168→    let flashloan = EModeFlashLoan {
   169→        flash_loan_fee_rate: flash_loan_fee_rate,
   170→    };
   171→    dynamic_field::add(&mut emode.id, DFKey<EModeFlashLoan> {}, flashloan);
   172→
   173→    let limiter = EModeRateLimiter {
   174→        deposit: limiter::new_from_struct(deposit_limiter),
   175→        borrow: limiter::new_from_struct(borrow_limiter),
   176→    };
   177→    dynamic_field::add(&mut emode.id, DFKey<EModeRateLimiter> {}, limiter);
   178→
   179→    group.assets.store<EMode, CoinType>(emode);
   180→    group.assets_borrows.store<Decimal, CoinType>(math::float::zero());
   181→}
