   183→public(package) fun update_asset_borrow(self: &mut EModeGroup, coin: TypeName, old_value: Decimal, new_value: Decimal): Decimal {
   184→    assert!(self.assets_borrows.supports_type(coin), error::emode_group_does_not_support_asset());
   185→
   186→    let current_borrow = self.assets_borrows.load_mut_by_type(coin);
   187→    // using saturating_sub, if the value is below 0, just let it be zero
   188→    let new_borrow = new_value.add(*current_borrow).saturating_sub(old_value);
   189→
   190→    *current_borrow = new_borrow;
   191→    new_borrow
   192→}
